46	    /// Adds the names of every `from <module> import A, B` line in `source`,
47	    /// ignoring other lines. Returns whether any name was new.
48	    pub fn add_from_source(&mut self, source: &str) -> bool {
49	        let mut added = false;
50	        for line in source.lines() {
51	            let Some((module, names)) = line
52	                .trim()
53	                .strip_prefix("from ")
54	                .and_then(|rest| rest.split_once(" import "))
55	            else {
56	                continue;
57	            };
58	            let names: Vec<&str> = names
59	                .split(',')
60	                .map(str::trim)
61	                .filter(|name| !name.is_empty())
62	                .collect();
63	            if names.is_empty() {
64	                continue;
65	            }
66	            let imported = self.0.entry(absolute_module(module.trim())).or_default();
67	            for name in names {
68	                added |= imported.insert(name.to_string());
69	            }
70	        }
71	        added
72	    }
