74	    /// Whether `name` is imported.
75	    pub fn has(&self, name: &str) -> bool {
76	        self.0.values().any(|names| {
77	            names
78	                .iter()
79	                .any(|imported| imported.rsplit(' ').next() == Some(name))
80	        })
81	    }
