149	    /// The Piton source of this anchor with `prompt` as its `userPrompt`.
150	    pub fn source(&self, prompt: &str) -> String {
151	        let mut source = String::new();
152	        for (module, names) in &self.imports.0 {
153	            let names: Vec<&str> = names.iter().map(String::as_str).collect();
154	            writeln!(source, "from {module} import {}", names.join(", ")).ok();
155	        }
156	        writeln!(source, "\nexport anchor {}:\n    userPrompt:", self.name).ok();
157	        push_block(&mut source, PROMPT_INDENT, prompt);
158	        if let Some(mode) = self.mode {
159	            source.push('\n');
160	            writeln!(source, "{MODE_PREFIX}{}", mode.key()).ok();
161	        }
162	        if self.sliced {
163	            source.push('\n');
164	            writeln!(source, "{SLICED_LINE}").ok();
165	        }
166	        if !self.attached_text.is_empty() {
167	            source.push('\n');
168	            source.push_str(ATTACHED_TEXT_LINE);
169	            source.push('\n');
170	            for (index, text) in self.attached_text.iter().enumerate() {
171	                writeln!(source, "{PROMPT_INDENT}{ATTACHMENT_KEY}{}:", index + 1).ok();
172	                push_block(&mut source, ATTACHMENT_INDENT, text);
173	            }
174	        }
175	        if let Some(system_prompt) = &self.system_prompt {
176	            source.push('\n');
177	            source.push_str(SYSTEM_PROMPT_LINE);
178	            source.push('\n');
179	            push_block(&mut source, PROMPT_INDENT, system_prompt);
180	        }
181	        let references = self.references(prompt);
182	        if !references.is_empty() {
183	            source.push('\n');
184	            source.push_str(REFERENCES_LINE);
185	            source.push('\n');
186	            for reference in references {
187	                writeln!(source, "{PROMPT_INDENT}- {reference}").ok();
188	            }
189	        }
190	        source
191	    }
