196	    /// read as more than text blanked out, character for character. Pasted
197	    /// braces, quotes, or colons then never stop the server finding what
198	    /// needs importing.
199	    pub fn draft_source(&self, prompt: &str) -> String {
200	        let mut source = String::new();
201	        for (module, names) in &self.imports.0 {
202	            let names: Vec<&str> = names.iter().map(String::as_str).collect();
203	            writeln!(source, "from {module} import {}", names.join(", ")).ok();
204	        }
205	        writeln!(source, "\nanchor {}:\n    userPrompt:", self.name).ok();
206	        for line in prompt.split('\n') {
207	            source.push_str(PROMPT_INDENT);
208	            source.push_str(&blank_for_lsp(line.trim_end_matches('\r')));
209	            source.push('\n');
210	        }
211	        source
212	    }
