231	    /// `text` with each reference to an imported name replaced by what it
232	    /// resolved to, and everything else as it is.
233	    fn resolve(&self, text: &str, resolved: &BTreeMap<String, String>) -> String {
234	        pieces(text)
235	            .into_iter()
236	            .map(|piece| match piece {
237	                Piece::Reference(reference, name) if self.imports.has(name) => {
238	                    resolved.get(reference).map_or(reference, String::as_str)
239	                }
240	                Piece::Reference(text, _) | Piece::Text(text) => text,
241	            })
242	            .collect()
243	    }
