245	    /// Reads back an anchor saved with [`Self::source`], with the prompt it
246	    /// holds. Anchors saved by earlier versions, their text as quoted pieces
247	    /// or as prose, read back too.
248	    pub fn parse(source: &str) -> Option<(Self, String)> {
249	        let mut imports = Imports::default();
250	        let mut lines = source.lines();
251	        let name = loop {
252	            let line = lines.next()?;
253	            if let Some(name) = line
254	                .strip_prefix("export ")
255	                .unwrap_or(line)
256	                .strip_prefix("anchor ")
257	                .and_then(|rest| rest.strip_suffix(':'))
258	            {
259	                break name.to_string();
260	            }
261	            imports.add_from_source(line);
262	        };
263	        if lines.next()?.trim() != "userPrompt:" {
264	            return None;
265	        }
266	        let lines: Vec<&str> = lines.collect();
267	        let (prompt, mut rest) = match read_escaped(&lines, PROMPT_INDENT) {
268	            Some(read) => read,
269	            None => {
270	                // Prompt lines are indented deeper, so only the properties
271	                // themselves match these lines.
272	                let property = |line: &&str| {
273	                    *line == SYSTEM_PROMPT_LINE
274	                        || *line == ATTACHED_TEXT_LINE
275	                        || *line == SLICED_LINE
276	                        || line.starts_with(MODE_PREFIX)
277	                };
278	                let end = lines.iter().position(property).unwrap_or(lines.len());
279	                let prompt = &lines[..end];
280	                let prompt = prompt.strip_suffix(&[""]).unwrap_or(prompt);
281	                (read_block(prompt), &lines[end..])
282	            }
283	        };
284	        // A blank line separates each property from the next.
285	        rest = rest.strip_prefix(&[""]).unwrap_or(rest);
286	        let mut mode = None;
287	        if let Some(key) = rest.first().and_then(|line| line.strip_prefix(MODE_PREFIX)) {
288	            mode = SendMode::from_key(key.trim());
289	            rest = &rest[1..];
290	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
291	        }
292	        let sliced = rest.first() == Some(&SLICED_LINE);
293	        if sliced {
294	            rest = &rest[1..];
295	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
296	        }
297	        let mut attached_text = Vec::new();
298	        if rest.first() == Some(&ATTACHED_TEXT_LINE) {
299	            rest = &rest[1..];
300	            let mut quoted: Vec<Vec<String>> = Vec::new();
301	            while let Some(line) = rest.first() {
302	                if line
303	                    .strip_prefix(PROMPT_INDENT)
304	                    .and_then(|key| key.strip_prefix(ATTACHMENT_KEY))
305	                    .is_some_and(|key| key.ends_with(':'))
306	                {
307	                    let (text, after) = read_escaped(&rest[1..], ATTACHMENT_INDENT)?;
308	                    attached_text.push(text);
309	                    rest = after;
310	                    continue;
311	                } else if *line == OLD_ATTACHMENT_ITEM {
312	                    quoted.push(Vec::new());
313	                } else if let Some(line) = line.strip_prefix(OLD_ATTACHMENT_LINE_PREFIX) {
314	                    quoted.last_mut()?.push(unquote(line)?);
315	                } else {
316	                    break;
317	                }
318	                rest = &rest[1..];
319	            }
320	            attached_text.extend(quoted.into_iter().map(|lines| lines.join("\n")));
321	            rest = rest.strip_prefix(&[""]).unwrap_or(rest);
322	        }
323	        let system_prompt = match rest.first() {
324	            Some(&SYSTEM_PROMPT_LINE) => Some(match read_escaped(&rest[1..], PROMPT_INDENT) {
325	                Some((text, _)) => text,
326	                None => {
327	                    let end = rest[1..]
328	                        .iter()
329	                        .position(|line| *line == REFERENCES_LINE)
330	                        .map_or(rest.len(), |end| end + 1);
331	                    read_block(&rest[1..end])
332	                }
333	            }),
334	            _ => None,
335	        };
