374	/// Adds `text` to `source` as a multi-line escape block at `indent`, which
375	/// Piton keeps exactly as it is. Its fence is three backslashes, or one more
376	/// than any line of the text made only of backslashes, so nothing in the text
377	/// closes it early.
378	fn push_block(source: &mut String, indent: &str, text: &str) {
379	    let fence = "\\".repeat(fence_length(text));
380	    writeln!(source, "{indent}{fence}").ok();
381	    for line in text.split('\n') {
382	        let line = line.trim_end_matches('\r');
383	        if line.is_empty() {
384	            source.push('\n');
385	        } else {
386	            writeln!(source, "{indent}{line}").ok();
387	        }
388	    }
389	    writeln!(source, "{indent}{fence}").ok();
390	}
391	
392	/// How many backslashes fence `text`'s escape block.
393	fn fence_length(text: &str) -> usize {
394	    text.split('\n')
395	        .map(str::trim)
396	        .filter(|line| !line.is_empty() && line.chars().all(|c| c == '\\'))
397	        .map(|line| line.len() + 1)
398	        .max()
399	        .unwrap_or(0)
400	        .max(3)
401	}
402	
403	/// The text of an escape block written by [`push_block`] at `indent` at the
404	/// start of `lines`, and the lines after it; `None` when `lines` don't start
405	/// with one.
406	fn read_escaped<'a, 'b>(lines: &'a [&'b str], indent: &str) -> Option<(String, &'a [&'b str])> {
407	    let fence = lines.first()?.strip_prefix(indent)?;
408	    if fence.len() < 3 || !fence.chars().all(|c| c == '\\') {
409	        return None;
410	    }
411	    let close = format!("{indent}{fence}");
412	    let end = 1 + lines[1..].iter().position(|line| *line == close)?;
413	    let text = lines[1..end]
414	        .iter()
415	        .map(|line| line.strip_prefix(indent).unwrap_or(line.trim_start()))
416	        .collect::<Vec<_>>()
417	        .join("\n");
418	    Some((text, &lines[end + 1..]))
419	}
