426	/// The line a quoted string, as earlier versions wrote them, holds.
427	fn unquote(quoted: &str) -> Option<String> {
428	    let inner = quoted.strip_prefix('"')?.strip_suffix('"')?;
429	    let mut line = String::with_capacity(inner.len());
430	    let mut chars = inner.chars();
431	    while let Some(c) = chars.next() {
432	        line.push(if c == '\\' { chars.next()? } else { c });
433	    }
434	    Some(line)
435	}
