666	/// the prompt as it was saved, with each reference resolved as `piton compile`
667	/// resolves it, a link to its reference document for an `@{…}` and its text
668	/// for a `${…}`.
669	pub fn compile(anchor: &HiddenAnchor, file: &Path, project_dir: &Path) -> Result<CompiledPrompt> {
670	    let source =
671	        fs::read_to_string(file).with_context(|| format!("could not read {}", file.display()))?;
672	    let (saved, prompt) =
673	        HiddenAnchor::parse(&source).ok_or_else(|| anyhow!("{} is no prompt", file.display()))?;
674	    let output = Command::new("piton")
675	        .arg("compile")
676	        .arg(file)
677	        .current_dir(project_dir)
678	        .output()
679	        .context("could not run `piton compile`")?;
680	    if !output.status.success() {
681	        let mut message = String::from_utf8_lossy(&output.stdout).into_owned();
682	        message.push_str(&String::from_utf8_lossy(&output.stderr));
683	        return Err(anyhow!("{}", message.trim()));
684	    }
685	
686	    let compiled: Value =
687	        serde_json::from_slice(&output.stdout).context("`piton compile` did not print JSON")?;
688	    let compiled = compiled
689	        .get(&anchor.name)
690	        .ok_or_else(|| anyhow!("the compiled output has no {}", anchor.name))?;
691	    let values = compiled
692	        .get("references")
693	        .and_then(Value::as_array)
694	        .map(Vec::as_slice)
695	        .unwrap_or_default();
696	    let file_dir = file
697	        .parent()
698	        .map(|dir| dir.canonicalize().unwrap_or_else(|_| dir.to_path_buf()))
699	        .unwrap_or_default();
700	    let references: Vec<(&str, &Value)> =
701	        saved.references(&prompt).into_iter().zip(values).collect();
702	    let resolved: BTreeMap<String, String> = references
703	        .iter()
704	        .map(|&(reference, value)| {
705	            let text = match value {
706	                // Sliced, the reference names what its slice, sent after the
707	                // prompt, is headed by.
708	                Value::String(target) if reference.starts_with('@') && saved.sliced => target
709	                    .rsplit_once(':')
710	                    .map_or_else(|| target.clone(), |(_, dotted)| dotted.to_string()),
711	                Value::String(target) if reference.starts_with('@') => {
712	                    link(target, &file_dir, project_dir).unwrap_or_else(|| target.clone())
713	                }
714	                Value::String(text) => text.clone(),
715	                other => other.to_string(),
716	            };
717	            (reference.to_string(), text)
718	        })
719	        .collect();
720	    let mut user_prompt = saved.resolve(&prompt, &resolved);
721	    if saved.sliced {
722	        // Each spec the prompt itself, not its system prompt, refers to,
723	        // once, in order.
724	        let in_prompt: Vec<&str> = pieces(&prompt)
725	            .into_iter()
726	            .filter_map(|piece| match piece {
727	                Piece::Reference(reference, _) => Some(reference),
728	                Piece::Text(_) => None,
729	            })
730	            .collect();
731	        let targets: Vec<&str> = references
732	            .iter()
733	            .filter(|(reference, _)| reference.starts_with('@') && in_prompt.contains(reference))
734	            .filter_map(|(_, value)| value.as_str())
735	            .collect();
736	        if !targets.is_empty() {
737	            user_prompt.push_str("\n\nSpec slices:");
738	            for target in targets {
739	                user_prompt.push_str("\n\n");
740	                user_prompt.push_str(slice(target, &file_dir, project_dir).trim_end());
741	            }
742	        }
743	    }
744	    Ok(CompiledPrompt {
745	        user_prompt: with_attached_text(&user_prompt, &saved.attached_text),
746	        system_prompt: saved
747	            .system_prompt
748	            .as_deref()
749	            .map(|text| saved.resolve(text, &resolved)),
