492	/// A piece of a prompt's line: text, or a reference or interpolation with the
493	/// name it starts with.
494	#[derive(Debug, PartialEq)]
495	enum Piece<'a> {
496	    Text(&'a str),
497	    Reference(&'a str, &'a str),
498	}
499	
500	/// `line` split into text and the `@{Name.path}` and `${Name.path}` in it.
501	fn pieces(line: &str) -> Vec<Piece<'_>> {
502	    let mut pieces = Vec::new();
503	    let mut text_start = 0;
504	    let mut at = 0;
505	    while at < line.len() {
506	        let rest = &line[at..];
507	        let reference = (rest.starts_with("@{") || rest.starts_with("${"))
508	            .then(|| rest[2..].find('}'))
509	            .flatten()
510	            .map(|close| &rest[2..2 + close])
511	            .filter(|path| is_identifier_path(path));
512	        match reference {
513	            Some(path) => {
514	                if text_start < at {
515	                    pieces.push(Piece::Text(&line[text_start..at]));
516	                }
517	                let end = at + 2 + path.len() + 1;
518	                let name = path.split('.').next().unwrap_or(path);
519	                pieces.push(Piece::Reference(&line[at..end], name));
520	                at = end;
521	                text_start = end;
522	            }
523	            None => at += rest.chars().next().map_or(1, char::len_utf8),
524	        }
525	    }
526	    if text_start < line.len() {
527	        pieces.push(Piece::Text(&line[text_start..]));
528	    }
529	    pieces
530	}
