532	/// Whether `path` is a dotted path of identifiers, each perhaps with
533	/// kebab-case tails, as a Piton reference is.
534	fn is_identifier_path(path: &str) -> bool {
535	    !path.is_empty()
536	        && path.split('.').all(|segment| {
537	            let mut parts = segment.split('-');
538	            let head = parts.next().unwrap_or_default();
539	            head.chars()
540	                .next()
541	                .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
542	                && head.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
543	                && parts.all(|tail| {
544	                    !tail.is_empty() && tail.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
545	                })
546	        })
547	}
