549	/// `line` for `piton lsp`: references, and one being typed, kept as they are;
550	/// letters, digits, and spaces between words kept; anything else, and
551	/// leading whitespace, replaced with as many underscores as it is UTF-16 units
552	/// long, so every position in the line stays where it was.
553	fn blank_for_lsp(line: &str) -> String {
554	    let mut out = String::with_capacity(line.len());
555	    let mut at = 0;
556	    while at < line.len() {
557	        let rest = &line[at..];
558	        if rest.starts_with("@{") || rest.starts_with("${") {
559	            let name_len = rest[2..]
560	                .find(|c: char| !(c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-')))
561	                .unwrap_or(rest.len() - 2);
562	            let mut end = 2 + name_len;
563	            if rest[end..].starts_with('}') {
564	                end += 1;
565	            }
566	            out.push_str(&rest[..end]);
567	            at += end;
568	            continue;
569	        }
570	        let c = rest.chars().next().unwrap_or(' ');
571	        let leading = out.chars().all(|c| c == '_');
572	        if c.is_alphanumeric() && c.len_utf16() == 1 || (c == ' ' && !leading) {
573	            out.push(c);
574	        } else {
575	            out.extend(std::iter::repeat_n('_', c.len_utf16()));
576	        }
577	        at += c.len_utf8();
578	    }
579	    out
580	}
