386	    /// A task from the history, as it ended: its run's output is replayed
387	    /// through the harness's parser.
388	    fn restore(saved: SavedPrompt) -> Self {
389	        let mut task = Self::new(saved.text.into());
390	        task.mode = anchor_mode(&saved.anchor);
391	        task.sent = SentAs::of(&saved.anchor);
392	        let Some(record) = saved.record else {
393	            task.reply.stop();
394	            task.status = TaskStatus::Unrecorded;
395	            return task;
396	        };
397	        if let Some(markdown) = record.user_prompt.clone() {
398	            task.set_compiled(Compiled::new(
399	                saved.anchor.name().to_string().into(),
400	                markdown,
401	            ));
402	        }
403	        for event in record.events() {
404	            task.apply(event);
405	        }
406	        if record.cancelled {
407	            task.cancel();
408	        } else if let Some(error) = record.error {
409	            task.apply(HarnessEvent::Failed(error));
410	        }
411	        task.end();
412	        task
413	    }
