2330	    fn apply_event(&mut self, ix: usize, event: HarnessEvent, cx: &mut Context<Self>) {
2331	        if ix >= self.tasks.len() {
2332	            return;
2333	        }
2334	        if self.in_background {
2335	            self.tasks[ix].apply(event);
2336	            return;
2337	        }
2338	        let latest = ix + 1 == self.tasks.len();
2339	        // A raw output line only changes the raw tail at the end of the
2340	        // output, so there is nothing to redraw while that is out of sight.
2341	        let unseen = matches!(event, HarnessEvent::Output(_))
2342	            && (!latest || self.task_history.expanded || !self.output_table.end_in_view());
2343	        // Follows new output only while already scrolled to the bottom.
2344	        let scroll = self.output_table.scroll();
2345	        let following = scroll.offset().y <= -scroll.max_offset().y + px(1.);
2346	        self.tasks[ix].apply(event);
2347	        if unseen {
2348	            return;
2349	        }
2350	        if (following || self.output_locked) && latest {
2351	            self.output_table.scroll_to_end();
2352	        }
2353	        cx.notify();
2354	    }
