600	        let line = self.raw_tail.get(ix)?;
601	        let theme = &cx.theme().highlight_theme;
602	        let key = Arc::as_ptr(theme) as usize;
603	        let mut cache = self.raw_styles.borrow_mut();
604	        let styles = match cache.get(ix) {
605	            Some(Some((for_theme, styles))) if *for_theme == key => styles.clone(),
606	            _ => {
