620	    /// The rows that may have changed height since change `edit`.
621	    fn changed_since(&self, edit: u64) -> impl Iterator<Item = usize> + '_ {
622	        let start = self.changes.partition_point(|(at, _)| *at <= edit);
623	        self.changes[start..].iter().map(|(_, row)| *row)
624	    }
625	
626	    /// Notes that row `ix` may have changed height.
627	    fn touch(&mut self, ix: usize) {
628	        self.edit += 1;
629	        match self.changes.last_mut() {
630	            Some((at, row)) if *row == ix => *at = self.edit,
631	            _ => self.changes.push((self.edit, ix)),
632	        }
633	    }
634	
635	    /// The row part `part` is shown as, if it is shown.
636	    fn row_of(&self, part: usize) -> Option<usize> {
637	        self.rows
638	            .binary_search_by(|row| match row {
639	                RowSource::Part(at) => at.cmp(&part),
640	                RowSource::Pending => std::cmp::Ordering::Greater,
641	            })
642	            .ok()
643	    }
644	
645	    /// Brings the rows up to date with the parts. Text with nothing in it is
646	    /// left out, unless it is the last thing in a reply still streaming. Until
647	    /// the reply is done, it ends in a row that is still filling in, adding a
648	    /// pending row if the last is already complete. Rows only change or are
649	    /// added at the end as the reply streams, so a row keeps its index, and
650	    /// only the rows from the last part on are gone over again.
651	    fn refresh(&mut self) {
652	        let settled = self.settled_parts;
653	        let keep = self
654	            .rows
655	            .partition_point(|row| matches!(row, RowSource::Part(part) if *part < settled));
656	        self.rows.truncate(keep);
657	        self.last_tool_row = self.last_tool_row.filter(|row| *row < keep);
658	        self.last_sent_row = self.last_sent_row.filter(|row| *row < keep);
659	        let last = self.parts.len().checked_sub(1);
660	        for (ix, part) in self.parts.iter().enumerate().skip(settled) {
661	            let shown = match part {
662	                ReplyPart::Text(text) => {
663	                    !(text.trim().is_empty() && (self.done || Some(ix) != last))
664	                }
665	                ReplyPart::Tool(_) => {
666	                    self.last_tool_row = Some(self.rows.len());
667	                    true
668	                }
669	                ReplyPart::Error(_) => true,
670	                ReplyPart::Sent(_) => {
671	                    self.last_sent_row = Some(self.rows.len());
672	                    true
673	                }
674	            };
675	            if shown {
676	                self.rows.push(RowSource::Part(ix));
677	            }
678	        }
679	        if !self.done && !self.last_row().is_some_and(|row| row.is_partial()) {
680	            self.rows.push(RowSource::Pending);
681	        }
682	        self.settled_parts = self.parts.len().saturating_sub(1);
683	        for ix in keep..self.rows.len() {
684	            self.touch(ix);
685	        }
686	    }
687	
688	    /// Folds a harness event into the reply. Returns an error to show when the
689	    /// run failed.
690	    pub(crate) fn apply(&mut self, event: HarnessEvent) -> Option<String> {
691	        match event {
692	            HarnessEvent::Output(mut line) => {
693	                if let Some((end, _)) = line.char_indices().nth(RAW_LINE_CHARS) {
694	                    line.truncate(end);
695	                }
696	                // Always as tall, however many lines there are, so no row
697	                // changes height.
698	                let styles = self.raw_styles.get_mut();
699	                if self.raw_tail.len() == RAW_TAIL_LINES {
700	                    self.raw_tail.pop_front();
701	                    styles.pop_front();
702	                }
703	                self.raw_tail.push_back(line);
704	                styles.push_back(None);
705	                return None;
706	            }
707	            HarnessEvent::TextStarted => self
708	                .parts
709	                .push(ReplyPart::Text(TextPart::new(String::new()))),
710	            HarnessEvent::TextDelta(delta) => match self.parts.last_mut() {
711	                Some(ReplyPart::Text(text)) => text.push_str(&delta),
712	                _ => self.parts.push(ReplyPart::Text(TextPart::new(delta))),
713	            },
714	            // A harness that reports a call again when it finishes starts it
715	            // again; it is still the one call.
716	            HarnessEvent::ToolStarted { id, .. } if self.tool_part(&id).is_some() => {}
717	            HarnessEvent::ToolStarted { id, name } => self.parts.push(ReplyPart::Tool(ToolCall {
718	                id,
719	                name,
720	                summary: None,
721	                state: ToolState::Running,
722	                shown: RefCell::default(),
723	            })),
724	            HarnessEvent::ToolInput { id, summary } => {
725	                if let Some(part) = self.tool_part(&id) {
726	                    if let ReplyPart::Tool(call) = &mut self.parts[part] {
727	                        call.summary = Some(summary);
728	                        call.shown = RefCell::default();
729	                    }
730	                    if let Some(row) = self.row_of(part) {
731	                        self.touch(row);
732	                    }
733	                }
734	            }
735	            HarnessEvent::ToolFinished { id, is_error } => {
736	                if let Some(part) = self.tool_part(&id) {
737	                    if let ReplyPart::Tool(call) = &mut self.parts[part] {
738	                        call.state = if is_error {
739	                            ToolState::Failed
740	                        } else {
741	                            ToolState::Done
742	                        };
743	                    }
744	                    if let Some(row) = self.row_of(part) {
745	                        self.touch(row);
746	                    }
747	                }
748	            }
749	            HarnessEvent::Finished { is_error, result } => {
750	                self.done = true;
751	                self.settle_tools(if is_error {
752	                    ToolState::Failed
753	                } else {
754	                    ToolState::Done
755	                });
756	                if is_error {
757	                    self.refresh();
758	                    return Some(if result.is_empty() {
759	                        "The harness reported an error.".into()
760	                    } else {
761	                        result
762	                    });
763	                }
764	                // Nothing streamed (e.g. an older harness): show the result.
765	                if !self.has_text() && !result.is_empty() {
766	                    self.parts.push(ReplyPart::Text(TextPart::new(result)));
767	                }
768	            }
769	            // A result that leaves messages sent to the run unanswered: the
770	            // calls it made are over, and the run goes on.
771	            HarnessEvent::Answered { is_error, result } => {
772	                self.settle_tools(if is_error {
773	                    ToolState::Failed
774	                } else {
775	                    ToolState::Done
776	                });
777	                if is_error {
778	                    self.parts.push(ReplyPart::Error(if result.is_empty() {
779	                        "The harness reported an error.".into()
780	                    } else {
781	                        result
782	                    }));
783	                }
784	            }
785	            HarnessEvent::Sent { text, .. } => self.parts.push(ReplyPart::Sent(text)),
786	            HarnessEvent::Failed(error) => {
787	                self.done = true;
788	                self.settle_tools(ToolState::Failed);
789	                self.refresh();
790	                return Some(error);
791	            }
792	            HarnessEvent::Session(_)
793	            | HarnessEvent::Usage { .. }
794	            | HarnessEvent::Spent { .. }
795	            | HarnessEvent::Limits(_)
796	            | HarnessEvent::Model(_)
797	            | HarnessEvent::ToolCalled { .. }
798	            | HarnessEvent::ToolOutput { .. } => return None,
799	        }
800	        self.refresh();
801	        None
802	    }
