820	    /// Gives tool calls still running when the run ended the state they ended
821	    /// in, so none is left reading "running".
822	    fn settle_tools(&mut self, state: ToolState) {
823	        let mut settled = Vec::new();
824	        for (ix, part) in self.parts.iter_mut().enumerate() {
825	            if let ReplyPart::Tool(call) = part
826	                && call.state == ToolState::Running
827	            {
828	                call.state = state;
829	                settled.push(ix);
830	            }
831	        }
832	        for part in settled {
833	            if let Some(row) = self.row_of(part) {
834	                self.touch(row);
835	            }
836	        }
837	    }
