888	impl Layout {
889	    /// With `steps_shown`, a finished reply's rows up to its last tool call
890	    /// collapse, unless there's nothing after it. A message sent to the run
891	    /// is never collapsed: the steps are those after the last one sent before
892	    /// the answer.
893	    pub(crate) fn of(reply: &Reply, steps_shown: Option<bool>) -> Self {
894	        let rows = reply.row_count();
895	        let steps = steps_shown.filter(|_| reply.is_done()).and_then(|shown| {
896	            let end = reply.last_tool_row? + 1;
897	            let start = reply
898	                .last_sent_row
899	                .filter(|sent| *sent < end)
900	                .map_or(0, |sent| sent + 1);
901	            (end < rows && start < end).then_some((start, end - start, shown))
902	        });
903	        Self { rows, steps }
904	    }
905	
906	    /// How many items it takes in a list.
907	    pub(crate) fn items(&self) -> usize {
908	        match self.steps {
909	            None => self.rows,
910	            Some((_, _, true)) => self.rows + 1,
911	            Some((_, steps, false)) => self.rows - steps + 1,
912	        }
913	    }
914	
915	    fn item(&self, item: usize) -> Item {
916	        match self.steps {
917	            None => Item::Row(item),
918	            Some((start, _, _)) if item < start => Item::Row(item),
919	            Some((start, _, _)) if item == start => Item::Steps,
920	            Some((_, _, true)) => Item::Row(item - 1),
921	            Some((_, steps, false)) => Item::Row(item - 1 + steps),
922	        }
923	    }
924	
925	    /// The item row `row` is, unless it's a step collapsed away.
926	    fn item_of(&self, row: usize) -> Option<usize> {
927	        match self.steps {
928	            None => Some(row),
929	            Some((start, _, _)) if row < start => Some(row),
930	            Some((_, _, true)) => Some(row + 1),
931	            Some((start, steps, false)) => (row >= start + steps).then(|| row - steps + 1),
932	        }
933	    }
